"""Random valid request generator for local protocol testing."""
import random


def build_adj(nodes, edges):
    adj = {n: [] for n in range(nodes)}
    for eid, (u, v, c) in enumerate(edges):
        adj[u].append((eid, v))
    return adj


def random_walk(adj, s, t, rng, max_len=12):
    path = []
    visited = {s}

    def dfs(node):
        if node == t:
            return True
        opts = list(adj[node])
        rng.shuffle(opts)
        for e, v in opts:
            if v in visited or len(path) >= max_len:
                continue
            visited.add(v)
            path.append(e)
            if dfs(v):
                return True
            path.pop()
            visited.discard(v)
        return False

    if dfs(s):
        return list(path)
    return None


def gen_case(rng, tight=False):
    nodes = rng.randint(2, 7)
    pairs = [(u, v) for u in range(nodes) for v in range(nodes) if u != v]
    rng.shuffle(pairs)
    nedges = rng.randint(1, min(len(pairs), 12))
    edges = []
    for (u, v) in pairs[:nedges]:
        cap = rng.choice([0, 0, 1, 1, 2, 3, 5, 10, 50, 1000])
        edges.append([u, v, cap])
    adj = build_adj(nodes, edges)
    ncom = rng.randint(0, 6)
    commodities = []
    total_slots = 0
    for _ in range(ncom):
        s = rng.randrange(nodes)
        t = rng.randrange(nodes)
        while t == s:
            t = rng.randrange(nodes)
        nslots = rng.randint(0, 4)
        if total_slots + nslots > 20:
            nslots = max(0, 20 - total_slots)
        total_slots += nslots
        slots = []
        used = set()
        for _ in range(nslots):
            if rng.random() < 0.15:
                slots.append(None)
                continue
            for _try in range(12):
                w = random_walk(adj, s, t, rng)
                if w is None:
                    break
                if tuple(w) not in used:
                    used.add(tuple(w))
                    slots.append(w)
                    break
            else:
                slots.append(None)
        commodities.append({"source": s, "sink": t,
                            "demand": rng.choice([0, 0, 1, 2, 3, 7, 100, 1000]),
                            "paths": slots})
    nworkers = rng.randint(1, 4)
    ids = list(range(ncom))
    rng.shuffle(ids)
    workers = [[] for _ in range(nworkers)]
    for i, k in enumerate(ids):
        workers[i % nworkers].append(k)
    for w in workers:
        w.sort()
    quorum = rng.randint(1, nworkers)
    max_lag = rng.randint(0, 4)
    a = rng.randint(1, 6)
    b = rng.randint(1, a)
    while not (b <= a < 2 * b):
        b = rng.randint(1, a)
    relax = [a, b]
    rho = rng.randint(1, 8)
    mode = rng.choice(["route", "admit"])
    events = gen_events(rng, nodes, edges, commodities, mode, nworkers, tight)
    return {
        "nodes": nodes, "edges": edges, "commodities": commodities,
        "workers": workers, "quorum": quorum, "max_lag": max_lag,
        "relax": relax, "rho": rho, "mode": mode, "events": events,
    }


def gen_events(rng, nodes, edges, commodities, mode, nworkers, tight):
    adj = build_adj(nodes, edges)
    events = []
    tickets = []
    saves = []
    budget = 14 if tight else 40
    cur_mode = mode
    while len(events) < budget:
        r = rng.random()
        if r < 0.10:
            ev = {"op": "configure", "mode": rng.choice(["route", "admit"]),
                  "capacity": [], "demand": [], "paths": []}
            used = set()
            for _ in range(rng.randint(0, 3)):
                eid = rng.randrange(len(edges))
                if eid in used:
                    continue
                used.add(eid)
                ev["capacity"].append([eid, rng.choice([0, 0, 1, 2, 5, 100, 1000])])
            used = set()
            for _ in range(rng.randint(0, 3)):
                cid = rng.randrange(len(commodities))
                if cid in used:
                    continue
                used.add(cid)
                ev["demand"].append([cid, rng.choice([0, 1, 2, 5, 100, 1000])])
            # path patches: simulate the slot state to keep distinctness
            slots = [list(c["paths"]) for c in commodities]
            used = set()
            for _ in range(rng.randint(0, 4)):
                cid = rng.randrange(len(commodities))
                pid = rng.randrange(len(slots[cid])) if slots[cid] else -1
                if pid < 0 or (cid, pid) in used:
                    continue
                com = commodities[cid]
                cand = None
                for _try in range(10):
                    w = random_walk(adj, com["source"], com["sink"], rng)
                    if w is None:
                        cand = None
                        break
                    trial = list(slots[cid])
                    trial[pid] = w
                    vals = [tuple(p) for p in trial if p is not None]
                    if len(vals) == len(set(vals)):
                        cand = w
                        break
                used.add((cid, pid))
                ev["paths"].append([cid, pid, cand])
                slots[cid][pid] = cand
            events.append(ev)
        elif r < 0.35 and len(tickets) < 12:
            tid = rng.randrange(0, 1000)
            while tid in [t["id"] for t in tickets]:
                tid = rng.randrange(0, 1000)
            ev = {"op": "issue", "id": tid, "worker": rng.randrange(nworkers)}
            tickets.append({"id": tid, "idx": len(events)})
            events.append(ev)
        elif r < 0.65 and tickets:
            ev = {"op": "deliver", "id": rng.choice(tickets)["id"]}
            events.append(ev)
        elif r < 0.78:
            events.append({"op": "step"})
        elif r < 0.84:
            events.append({"op": "retune", "rho": rng.randint(1, 8)})
        elif r < 0.90:
            name = rng.randrange(0, 1000)
            while name in saves:
                name = rng.randrange(0, 1000)
            saves.append(name)
            events.append({"op": "save", "name": name})
        elif r < 0.96 and saves:
            events.append({"op": "restore", "name": rng.choice(saves)})
        else:
            events.append({"op": "audit"})
    if not events:
        events.append({"op": "step"})
    return events


def gen_request(rng, ncases=None, tight=False):
    if ncases is None:
        ncases = rng.randint(0, 4)
    cases = [gen_case(rng, tight) for _ in range(ncases)]
    total_events = sum(len(c["events"]) for c in cases)
    total_issues = sum(1 for c in cases for e in c["events"] if e["op"] == "issue")
    while total_events > 384 or total_issues > 48:
        cases = cases[:max(1, len(cases) // 2)]
        total_events = sum(len(c["events"]) for c in cases)
        total_issues = sum(1 for c in cases for e in c["events"] if e["op"] == "issue")
    return {"cases": cases}
